1486	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1487	// 分配更正、撤销收款或退款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1488	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1489	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值；退款在其发生
1490	// 序号减少本账单实收，不可撤销。
1491	type ledgerEvent struct {
1492		seq           int64  // 全局操作序号（调整/收款/更正/退款及其撤销共用）
1493		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款 / 退款
1494		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1495		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1496		deltaReceived int64  // 对实收的影响（分，带符号）
1497		note          string // 原因（调整/更正类）或备注（收款类）
1498		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1499		payTotal      int64  // 收款类事件：汇款总额
1500		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配；退款事件为本账单退款额）
1501		payID         string // 更正/退款事件：关联收款标识
1502		beforeAlloc   int64  // 更正事件：本账单更正前分配
1503		afterAlloc    int64  // 更正事件：本账单更正后分配
1504		afterPayable  int64  // 事件后的应付（回放时填充）
1505		afterReceived int64  // 事件后的实收（回放时填充）
1506	}
1507	
1508	// billLedger 把目标账单的调整、调整撤销、收款、分配更正与收款撤销合并为
1509	// 一条按操作序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，
1510	// 填充每个事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：
1511	// 序号重复、撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号
1512	// 64 位最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1513	// 只读：不修改库、不占用序号、不新增记录。
1514	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1515		var events []ledgerEvent
1516		for _, a := range s.Adjustments {
1517			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1518				continue
1519			}
1520			events = append(events, ledgerEvent{
1521				seq: a.Seq, kind: "调整", refID: a.ID,
1522				deltaPayable: a.Amount, note: a.Reason,
1523			})
1524			if a.Revoked {
1525				neg, err := neg64(a.Amount)
1526				if err != nil {
1527					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1528				}
1529				events = append(events, ledgerEvent{
1530					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1531					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1532				})
1533			}
1534		}
1535		for _, p := range s.Payments {
1536			if p.CustomerID != b.CustomerID {
1537				continue
1538			}
1539			// 多月汇款只以本账单分配改变实收；更正在其发生序号把本账单分配
1540			// 由前值替换为后值；整笔撤销在同一序号取消撤销时的最新分配。
1541			// 首次登记或任一次更正涉及本账单的，该收款的后续事件都纳入流水。
1542			alloc := p.amountFor(b.Month)
1543			corrs := correctionsFor(s, p.ID)
1544			involved := alloc > 0
1545			if !involved {
1546				for _, c := range corrs {
1547					if allocAmountFor(c.Allocations, b.Month) > 0 {
1548						involved = true
1549						break
1550					}
1551				}
1552			}
1553			if !involved {
1554				continue
1555			}
1556			if alloc > 0 {
1557				events = append(events, ledgerEvent{
1558					seq: p.Seq, kind: "收款", refID: p.ID,
1559					deltaReceived: alloc, note: p.Note,
1560					payTotal: p.Total, payAlloc: alloc,
1561				})
1562			}
1563			running := alloc
1564			for _, c := range corrs {
1565				after := allocAmountFor(c.Allocations, b.Month)
1566				if running == 0 && after == 0 {
1567					continue // 本次更正不涉及本账单
1568				}
1569				events = append(events, ledgerEvent{
1570					seq: c.Seq, kind: "更正", refID: c.ID,
1571					deltaReceived: after - running, note: c.Reason,
1572					payID: p.ID, beforeAlloc: running, afterAlloc: after,
1573				})
1574				running = after
1575			}
1576			if p.Revoked {
1577				events = append(events, ledgerEvent{
1578					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1579					deltaReceived: -running, note: p.RevokeReason, linkSeq: p.Seq,
1580					payTotal: p.Total, payAlloc: running,
1581				})
1582			}
1583			// 退款在其发生序号减少本账单实收；退款月份必属于最新分配，故该收款
1584			// 必然已被上面的“涉及本账单”判断纳入。
1585			for _, r := range refundsFor(s, p.ID) {
1586				amt := allocAmountFor(r.Allocations, b.Month)
1587				if amt <= 0 {
1588					continue // 本次退款不涉及本账单
1589				}
1590				events = append(events, ledgerEvent{
1591					seq: r.Seq, kind: "退款", refID: r.ID,
1592					deltaReceived: -amt, note: r.Reason,
1593					payID: p.ID, payAlloc: amt,
1594				})
1595			}
1596		}
1597		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1598	
1599		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1600		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1601		// 仍能成功。
1602		payable := b.TotalFee
1603		var received int64
1604		seen := make(map[int64]string, len(events))
1605		for i := range events {
1606			ev := &events[i]
1607			desc := ev.kind + " " + ev.refID
1608			if prev, dup := seen[ev.seq]; dup {
1609				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1610			}
1611			seen[ev.seq] = desc
1612			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1613				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1614			}
1615			var err error
1616			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1617				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1618			}
1619			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1620				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1621			}
1622			if payable < 0 {
1623				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1624			}
1625			if received < 0 {
1626				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1627			}
1628			if received > payable {
1629				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1630			}
1631			ev.afterPayable = payable
