915	// tiersEqual 判定两份阶梯规则完全相同。
916	func tiersEqual(a, b []tier) bool {
917		if len(a) != len(b) {
918			return false
919		}
920		for i := range a {
921			if a[i] != b[i] {
922				return false
923			}
924		}
925		return true
926	}
