	h.mustRun("bill", "pay", "c1", "2026-09", "same-id", "100", "同名收款")   // 序号 1
	h.mustRun("bill", "adjust", "c1", "2026-09", "same-id", "10", "同名调整") // 序号 2
	h.mustRun("bill", "revoke", "same-id", "撤销调整")                        // 序号 3：只撤销调整

