			t.Fatalf("2026-02 流水缺少 %q：\n%s", want, ledger2)
		}
	}

	// 历史截止：截止 2 时报表与 ledger 逐月一致；截止后的更正不提前影响。
	cut := h.mustRun("bill", "reconcile", "c1", "2026-01", "2026-02", "0", "2")
	for _, want := range []string{
